// ---------------------------------------------------------------
// Interpreta los comandos del registro de hábitos.
// accion: registrar | listar | hoy | stats | ayuda | error
// ---------------------------------------------------------------
const AYUDA = [
  'Registro de hábitos - comandos:',
  '/habito nombre [nota] - registra el hábito de hoy',
  '   ejemplo: /habito leer 20 páginas de un libro',
  '/habitos - lista los hábitos disponibles',
  '/hoy - hábitos cumplidos y pendientes de hoy',
  '/stats [días] - porcentaje de cumplimiento (7 por defecto, máximo 90)',
].join('\n');

function interpretarHabito(textoOriginal, chatId) {
  const base = { chatId: String(chatId || '') };
  const texto = String(textoOriginal || '').trim();
  if (!texto.startsWith('/')) {
    return { ...base, accion: 'error', respuesta: 'Usa un comando, por ejemplo /habito leer\n\n' + AYUDA };
  }
  const [primera, ...resto] = texto.split(/\s+/);
  const comando = primera.toLowerCase().split('@')[0];

  if (['/start', '/ayuda', '/help'].includes(comando)) return { ...base, accion: 'ayuda', respuesta: AYUDA };
  if (comando === '/habitos') return { ...base, accion: 'listar' };
  if (comando === '/hoy') return { ...base, accion: 'hoy' };
  if (comando === '/stats') {
    const dias = resto[0] ? Number(resto[0]) : 7;
    if (!Number.isInteger(dias) || dias < 1 || dias > 90) {
      return { ...base, accion: 'error', respuesta: 'El número de días debe ser un entero entre 1 y 90. Ejemplo: /stats 30' };
    }
    return { ...base, accion: 'stats', dias };
  }
  if (comando === '/habito') {
    if (resto.length === 0) {
      return { ...base, accion: 'error', respuesta: 'Indica el hábito. Ejemplo: /habito leer\nConsulta la lista con /habitos' };
    }
    const nota = resto.slice(1).join(' ').slice(0, 300);
    return { ...base, accion: 'registrar', habito: resto[0], nota };
  }
  return { ...base, accion: 'error', respuesta: `Comando no reconocido: ${comando}\n\n${AYUDA}` };
}

const entrada = $('Entrada del router').first().json;
return [{ json: interpretarHabito(entrada.texto, entrada.chatId) }];

// ---------------------------------------------------------------
// Utilidades de hábitos: normalización y estadísticas.
// ---------------------------------------------------------------
const normalizar = (t) => String(t || '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .trim().toLowerCase();

const esActivo = (v) => v === true || ['si', 'true', '1', 'yes', 'activo'].includes(normalizar(v));

function leerNodo(nombre) {
  try {
    return $(nombre).all().map((i) => i.json);
  } catch (error) {
    return [];
  }
}

function habitosActivos(filas) {
  return filas
    .filter((h) => h && h.habito && esActivo(h.activo))
    .map((h) => ({
      habito: normalizar(h.habito),
      descripcion: h.descripcion || '',
      metaSemanal: Math.min(7, Math.max(1, Number(h.meta_semanal) || 7)),
    }));
}

function registrosDelChat(filas, chatId) {
  return filas
    .filter((r) => r && r.habito && r.fecha)
    .filter((r) => !chatId || String(r.chat_id) === String(chatId))
    .map((r) => ({ ...r, habito: normalizar(r.habito), fecha: String(r.fecha).slice(0, 10) }));
}

// Porcentaje de cumplimiento en los últimos "dias" días (incluido hoy).
function calcularEstadisticas(habitos, registros, dias) {
  const desde = $now.minus({ days: dias - 1 }).toFormat('yyyy-MM-dd');
  const hasta = $now.toFormat('yyyy-MM-dd');
  return habitos.map((h) => {
    const fechas = new Set(registros
      .filter((r) => r.habito === h.habito && r.fecha >= desde && r.fecha <= hasta)
      .map((r) => r.fecha));
    const objetivo = Math.max(1, Math.round((h.metaSemanal * dias) / 7));
    const porcentaje = Math.min(100, Math.round((fechas.size / objetivo) * 100));
    return { habito: h.habito, diasCumplidos: fechas.size, objetivo, porcentaje };
  });
}

function barra(porcentaje) {
  const llenos = Math.round(porcentaje / 10);
  return '#'.repeat(llenos) + '-'.repeat(10 - llenos);
}

function textoEstadisticas(estadisticas, dias) {
  if (estadisticas.length === 0) return 'No hay hábitos activos en la hoja Habitos.';
  const media = Math.round(estadisticas.reduce((s, e) => s + e.porcentaje, 0) / estadisticas.length);
  const lineas = estadisticas
    .sort((a, b) => b.porcentaje - a.porcentaje)
    .map((e) => `${barra(e.porcentaje)} ${String(e.porcentaje).padStart(3)}%  ${e.habito} (${e.diasCumplidos}/${e.objetivo} días)`);
  return [`Cumplimiento de los últimos ${dias} días`, '', ...lineas, '', `Media global: ${media}%`].join('\n');
}

// ---------------------------------------------------------------
// Ejecuta la acción solicitada con los datos leídos de Google Sheets.
// Si hay que guardar un registro, devuelve guardar = true y la fila.
// ---------------------------------------------------------------
const peticion = $('Interpretar hábito').first().json;
const habitos = habitosActivos(leerNodo('Leer hábitos'));
const registros = registrosDelChat(leerNodo('Leer registro'), peticion.chatId);
const hoy = $now.toFormat('yyyy-MM-dd');
const salida = { chatId: peticion.chatId, guardar: false };

switch (peticion.accion) {
  case 'ayuda':
  case 'error':
    salida.respuesta = peticion.respuesta;
    break;

  case 'listar':
    salida.respuesta = habitos.length === 0
      ? 'No hay hábitos activos. Añádelos en la pestaña Habitos de tu hoja.'
      : 'Hábitos disponibles:\n\n' + habitos.map((h) => `- ${h.habito}: ${h.descripcion} (meta ${h.metaSemanal} días/semana)`).join('\n');
    break;

  case 'hoy': {
    const hechos = new Set(registros.filter((r) => r.fecha === hoy).map((r) => r.habito));
    const cumplidos = habitos.filter((h) => hechos.has(h.habito)).map((h) => `- ${h.habito}`);
    const pendientes = habitos.filter((h) => !hechos.has(h.habito)).map((h) => `- ${h.habito}`);
    salida.respuesta = [
      `Hábitos de hoy (${hoy}): ${cumplidos.length}/${habitos.length}`,
      '', 'Cumplidos:', ...(cumplidos.length ? cumplidos : ['- ninguno todavía']),
      '', 'Pendientes:', ...(pendientes.length ? pendientes : ['- ninguno, buen trabajo']),
    ].join('\n');
    break;
  }

  case 'stats':
    salida.respuesta = textoEstadisticas(calcularEstadisticas(habitos, registros, peticion.dias), peticion.dias);
    break;

  case 'registrar': {
    const buscado = normalizar(peticion.habito);
    const exactos = habitos.filter((h) => h.habito === buscado);
    const candidatos = exactos.length ? exactos : habitos.filter((h) => h.habito.startsWith(buscado));
    if (candidatos.length !== 1) {
      salida.respuesta = candidatos.length === 0
        ? `No existe el hábito "${peticion.habito}". Consulta la lista con /habitos`
        : `"${peticion.habito}" coincide con varios hábitos: ${candidatos.map((c) => c.habito).join(', ')}. Escribe el nombre completo.`;
      break;
    }
    const habito = candidatos[0].habito;
    if (registros.some((r) => r.habito === habito && r.fecha === hoy)) {
      salida.respuesta = `Ya registraste "${habito}" hoy. Solo se cuenta una vez por día.`;
      break;
    }
    salida.guardar = true;
    salida.fecha = hoy;
    salida.habito = habito;
    salida.chat_id = peticion.chatId;
    salida.nota = peticion.nota || '';
    salida.registrado_en = $now.toFormat('yyyy-MM-dd HH:mm');
    const semana = calcularEstadisticas(candidatos, [...registros, { habito, fecha: hoy }], 7)[0];
    salida.respuesta = `Registrado: ${habito} (${hoy})\nÚltimos 7 días: ${semana.diasCumplidos}/${semana.objetivo} días, ${semana.porcentaje}% de tu meta.`;
    break;
  }

  default:
    salida.respuesta = 'Acción no soportada.';
}

return [{ json: salida }];

// La respuesta se calculó antes de guardar; se recupera del nodo anterior.
const resultado = $('Procesar hábito').first().json;
return [{ json: { chatId: resultado.chatId, respuesta: resultado.respuesta } }];
